# -*- coding: utf-8 -*-
"""Семейства неисправностей: одно объяснение на группу кодов.

story   — как узел работает, что именно сравнил блок, почему выпал код и к чему это ведёт (цепочка).
confirm — что на датчиках подтверждает или опровергает причину (приложение это показывает).
causes  — частые причины, дешёвое и частое раньше.
do      — что делать по порядку.
stop    — при активном коде лучше не ехать.
links   — связь с другими семействами: если в той же проверке есть код из связанного семейства,
          показываем цепочку «этот код → тот код».
"""

F = {}


def fam(key, title, story, causes, do, severity="medium", confirm="", stop=False, links=None):
    assert key not in F, key
    F[key] = dict(title=title, story=story.strip(), causes=causes, do=do.strip(), severity=severity,
                  confirm=confirm.strip(), stop=stop, links=links or {})


